# Dated account behavior with explicit knowledge and history coverage.
.cr_rb_window<-function(as_of,information_cutoff,lookback_days,context){times<-.cr_rf_cutoffs(as_of,information_cutoff,context);days<-.cr_data_days(lookback_days,'lookback_days',1);if(days>=as.numeric(times$anchor-as.Date('0001-01-01'))+1) .cr_error('RETAIL_DATE','Observation window precedes supported calendar');c(times,list(days=days,start=times$anchor-days))}
.cr_rb_coverage<-function(coverage,cutoff,start,anchor){if(!.cr_object(coverage)) .cr_error('RETAIL_COVERAGE','Explicit dated historical coverage required');.cr_data_required(coverage,c('status','known_at','observed_from','complete_through'));if(!(coverage$status%in%c('COMPLETE','PARTIAL','UNKNOWN'))||.cr_data_date(coverage$known_at,'coverage.known_at')>cutoff) .cr_error('RETAIL_COVERAGE','Coverage status must be known at cutoff');first<-.cr_data_date(coverage$observed_from,'coverage.observed_from');last<-.cr_data_date(coverage$complete_through,'coverage.complete_through');if(last<first||last>.cr_data_date(coverage$known_at,'coverage.known_at')) .cr_error('RETAIL_COVERAGE','Coverage interval or receipt chronology invalid');coverage$status=='COMPLETE'&&first<=start+1&&last>=anchor}

build_payment_history_features<-function(obligations,payments,coverage,account_id,as_of,information_cutoff,lookback_days,allocation_policy,currency,grace_days,context=NULL){times<-.cr_rb_window(as_of,information_cutoff,lookback_days,context);anchor<-times$anchor;cutoff<-times$cutoff;ctx<-times$context;days<-times$days;start<-times$start;.cr_rf_text(account_id,'account_id');.cr_rf_text(currency,'currency');grace<-.cr_data_days(grace_days,'grace_days');complete<-.cr_rb_coverage(coverage,cutoff,start,anchor);if(!is.null(ctx$currency)&&ctx$currency!=currency) .cr_error('TARGET_MISMATCH','Context currency differs from payment currency');obs<-.cr_data_rows(obligations,'obligations');pays<-.cr_data_rows(payments,'payments');if(any(vapply(c(obs,pays),function(r)!identical(r$account_id,account_id),logical(1)))) .cr_error('RETAIL_ENTITY','Supply only the explicitly requested account ledger')
 replay<-function(date){r<-compute_days_past_due(obs,pays,as.character(date),as.character(min(cutoff,date)),allocation_policy,currency)$value;for(k in c('past_due_amount','unpaid_due_amount','net_payments','unallocated_payments'))if(!is.finite(r[[k]])) .cr_error('NUMERICAL_FAILURE','Historical ledger total outside finite range');r};daily<-list();cache<-list();transitions<-list()
 for(offset in seq_len(days)){date<-start+offset;r<-replay(date);cache[[as.character(date)]]<-r;state<-if(r$past_due_amount>0)'ARREARS'else 'CURRENT';daily[[length(daily)+1L]]<-list(date=as.character(date),information_cutoff=as.character(min(cutoff,date)),dpd=r$dpd,past_due_amount=r$past_due_amount,unpaid_due_amount=r$unpaid_due_amount,state=state);if(length(daily)>1&&daily[[length(daily)-1L]]$state!=state)transitions[[length(transitions)+1L]]<-list(date=as.character(date),from_state=daily[[length(daily)-1L]]$state,to_state=state)}
 assessments<-list();not_assessable<-list();for(obligation in .cr_rf_sort(obs,c('due_at','obligation_id'))){due<-.cr_data_date(obligation$due_at,'due_at');known<-.cr_data_date(obligation$known_at,'known_at');if(!(start<due&&due<=anchor)||known>cutoff)next;if(grace>as.numeric(anchor-due)){not_assessable[[length(not_assessable)+1L]]<-list(obligation_id=obligation$obligation_id,reason='GRACE_NOT_ELAPSED');next};assessment<-due+grace;if(known>min(cutoff,assessment)){not_assessable[[length(not_assessable)+1L]]<-list(obligation_id=obligation$obligation_id,reason='OBLIGATION_NOT_CONTEMPORANEOUSLY_KNOWN');next};r<-cache[[as.character(assessment)]];if(is.null(r))r<-replay(assessment);item<-Filter(function(v)v$obligation_id==obligation$obligation_id,r$obligations)[[1]];amount<-item$amount;paid<-item$applied;state<-if(amount==0)'ZERO_OBLIGATION'else if(paid==0)'MISSED'else if(paid<amount)'PARTIAL'else 'FULL';assessments[[length(assessments)+1L]]<-list(obligation_id=obligation$obligation_id,due_at=obligation$due_at,assessment_at=as.character(assessment),amount=amount,applied=paid,payment_ratio=if(amount==0)NULL else paid/amount,state=state)}
 count<-function(state)sum(vapply(assessments,function(r)r$state==state,logical(1)));amount<-.cr_loss_sum(vapply(assessments,`[[`,numeric(1),'amount'));applied<-.cr_loss_sum(vapply(assessments,`[[`,numeric(1),'applied'));known_features<-list(max_dpd=max(vapply(daily,`[[`,numeric(1),'dpd')),mean_dpd=.cr_loss_sum(vapply(daily,function(r)r$dpd/days,numeric(1))),arrears_days=sum(vapply(daily,function(r)r$past_due_amount>0,logical(1))),missed_payment_count=count('MISSED'),partial_payment_count=count('PARTIAL'),full_payment_count=count('FULL'),assessment_payment_ratio=if(amount==0)NULL else applied/amount)
 .cr_result(list(account_id=account_id,as_of=as_of,information_cutoff=information_cutoff,currency=currency,lookback_days=days,grace_days=grace,coverage_complete=complete,known_history_features=known_features,features=if(complete)known_features else setNames(rep(list(NULL),length(known_features)),names(known_features)),daily_history=daily,assessments=assessments,not_assessable=not_assessable,transitions=transitions),'retail_features.build_payment_history_features','account_behavior',ctx,diagnostics=list(allocation_policy=allocation_policy,coverage=coverage,knowledge_policy='MIN_EVALUATION_CUTOFF_AND_HISTORICAL_DATE'),limitations=list('Replay requires complete historical contractual obligations and payment/reversal ledger, including pre-window balances and prepayments. Source coverage is asserted, never inferred from an empty ledger. Each historical date uses only knowledge then available; late-known reversals do not rewrite earlier days. Grace changes only the assessment date, never the contractual due date or DPD. Current/arrears are descriptive unpaid-ledger states, not regulatory default labels.'))}

build_revolving_features<-function(balance_history,statements,coverage,account_id,as_of,information_cutoff,lookback_days,currency,context=NULL){times<-.cr_rb_window(as_of,information_cutoff,lookback_days,context);anchor<-times$anchor;cutoff<-times$cutoff;ctx<-times$context;days<-times$days;start<-times$start;.cr_rf_text(account_id,'account_id');.cr_rf_text(currency,'currency');complete<-.cr_rb_coverage(coverage,cutoff,start,anchor);if(!is.null(ctx$currency)&&ctx$currency!=currency) .cr_error('TARGET_MISMATCH','Context currency differs from revolving currency');release<-.cr_rf_releases(balance_history,'snapshot_id',cutoff,'balance history');daily<-list();seen<-character()
 for(row in release$rows){.cr_data_required(row,c('account_id','observed_at','balance','credit_limit','activity_status','currency'));observed<-.cr_data_date(row$observed_at,'observed_at');if(observed>.cr_data_date(row$known_at,'known_at')) .cr_error('RETAIL_DATE','Balance observation cannot follow receipt');if(row$account_id!=account_id||row$currency!=currency) .cr_error('RETAIL_ENTITY','Revolving history must match account and currency');balance<-.cr_rf_number(row$balance,'balance',0);limit<-.cr_rf_number(row$credit_limit,'credit_limit',0);if(!(row$activity_status%in%c('ACTIVE','INACTIVE','CLOSED'))) .cr_error('RETAIL_INPUT','Explicit activity status required; zero draw does not imply inactivity');if(row$activity_status=='CLOSED'&&(balance!=0||limit!=0)) .cr_error('RETAIL_INPUT','Closed facility requires zero residual balance and limit');if(!(start<observed&&observed<=anchor))next;if(row$observed_at%in%seen) .cr_error('DATA_DUPLICATE','One resolved balance snapshot per account and day required');seen<-c(seen,row$observed_at);utilization<-if(limit==0)NULL else balance/limit;if(!is.null(utilization)&&!is.finite(utilization)) .cr_error('NUMERICAL_FAILURE','Utilization outside finite range');daily[[length(daily)+1L]]<-list(date=row$observed_at,balance=balance,credit_limit=limit,utilization=utilization,overlimit=balance>limit,activity_status=row$activity_status,undrawn_active=row$activity_status=='ACTIVE'&&balance==0,snapshot_id=row$snapshot_id,release_seq=row$release_seq)}
 daily<-.cr_rf_sort(daily,'date');complete<-complete&&length(daily)==days;changes<-list();if(length(daily)>1)for(i in 2:length(daily)){previous<-daily[[i-1L]];current<-daily[[i]];db<-.cr_loss_sum(c(current$balance,-previous$balance));dl<-.cr_loss_sum(c(current$credit_limit,-previous$credit_limit));du<-balance_effect<-limit_effect<-NULL;if(previous$credit_limit>0&&current$credit_limit>0){du<-.cr_loss_sum(c(current$utilization,-previous$utilization));balance_effect<-db/current$credit_limit;limit_effect<-previous$utilization*(-dl/current$credit_limit);if(any(!is.finite(c(balance_effect,limit_effect)))) .cr_error('NUMERICAL_FAILURE','Utilization change decomposition outside finite range')};changes[[length(changes)+1L]]<-list(from_date=previous$date,to_date=current$date,elapsed_days=as.numeric(.cr_data_date(current$date,'date')-.cr_data_date(previous$date,'date')),balance_change=db,limit_change=dl,utilization_change=du,balance_effect_at_new_limit=balance_effect,limit_effect_on_previous_balance=limit_effect)}
 statements_release<-.cr_rf_releases(statements,'statement_id',cutoff,'statements');assessments<-list();pending<-character();for(row in statements_release$rows){.cr_data_required(row,c('account_id','issued_at','due_at','observed_at','statement_balance','minimum_due','paid_by_due','currency'));issued<-.cr_data_date(row$issued_at,'issued_at');due<-.cr_data_date(row$due_at,'due_at');observed<-.cr_data_date(row$observed_at,'observed_at');if(!(issued<=observed&&observed<=.cr_data_date(row$known_at,'known_at'))||due<issued) .cr_error('RETAIL_DATE','Statement dates or receipt chronology invalid');if(row$account_id!=account_id||row$currency!=currency) .cr_error('RETAIL_ENTITY','Statement must match account and currency');balance<-.cr_rf_number(row$statement_balance,'statement_balance',0);minimum<-.cr_rf_number(row$minimum_due,'minimum_due',0);paid<-.cr_rf_number(row$paid_by_due,'paid_by_due',0);if(minimum>balance) .cr_error('RETAIL_INPUT','Minimum payment cannot exceed supplied statement payable balance');if(!(start<due&&due<=anchor))next;if(observed<due){pending<-c(pending,row$statement_id);next};state<-if(balance==0)'NO_AMOUNT_DUE'else if(paid>=balance)'FULL'else if(paid>=minimum)'MINIMUM_MET'else 'BELOW_MINIMUM';assessment<-list(statement_id=row$statement_id,due_at=row$due_at,statement_balance=balance,minimum_due=minimum,paid_by_due=paid,full_repayment_ratio=if(balance==0)NULL else paid/balance,minimum_repayment_ratio=if(minimum==0)NULL else paid/minimum,repayment_state=state);if(any(!is.finite(c(assessment$full_repayment_ratio,assessment$minimum_repayment_ratio)))) .cr_error('NUMERICAL_FAILURE','Repayment ratio outside finite range');assessments[[length(assessments)+1L]]<-assessment}
 assessments<-.cr_rf_sort(assessments,c('due_at','statement_id'));utilizations<-unlist(lapply(daily,function(r)r$utilization),use.names=FALSE);latest<-if(length(daily))tail(daily,1)[[1]]else NULL;trend<-NULL;if(length(daily)>1&&!is.null(daily[[1]]$utilization)&&!is.null(latest$utilization))trend<-.cr_loss_sum(c(latest$utilization,-daily[[1]]$utilization))/as.numeric(.cr_data_date(latest$date,'date')-.cr_data_date(daily[[1]]$date,'date'));overlimit<-sum(vapply(daily,`[[`,logical(1),'overlimit'));count<-function(state)sum(vapply(assessments,function(r)r$repayment_state==state,logical(1)))
 .cr_result(list(account_id=account_id,as_of=as_of,information_cutoff=information_cutoff,currency=currency,lookback_days=days,coverage_complete=complete,observed_days=length(daily),missing_days=days-length(daily),known_overlimit_days=overlimit,overlimit_days=if(complete)overlimit else NULL,latest_snapshot=latest,mean_observed_utilization=if(!length(utilizations))NULL else .cr_loss_sum(utilizations/length(utilizations)),utilization_endpoint_trend_per_day=trend,balance_changes=changes,daily_history=daily,statement_assessments=assessments,unmatured_statement_ids=as.list(sort(pending)),full_payer_count=count('FULL'),minimum_without_full_count=count('MINIMUM_MET'),below_minimum_count=count('BELOW_MINIMUM')),'retail_features.build_revolving_features','account_behavior',ctx,diagnostics=list(coverage=coverage,excluded_balance_releases=release$excluded,excluded_statement_releases=statements_release$excluded),limitations=list('Balances are nonnegative drawn exposure, not signed deposit credits. Missing daily observations are not carried forward or counted as zero overlimit days. Utilization changes are decomposed using new-limit balance movement plus the effect of changing the limit on the previous balance; this describes balance movement, not gross draw transactions. Supplied paid_by_due must be the allocated amount by contractual due date, not payments observed after it. Activity is supplied explicitly and is not inferred from zero balance.'))}
